mapper.select:
select p.close_begin_time, p.close_end_time, p.id as projectId, p.project_code, p.project_name, p.user_id, su.nick_name, ps.stage_code, ps.stage_name, p.type as projectType, p.status, p.published, p.project_process, p.created_time, p.updated_time, p.description, p.cover, p.auto_update_process, p.open_prefix, p.prefix, p.open_task_private, p.msg_notify, p.notify_day from pmhub_project p left join pmhub_project_stage ps on p.project_stage_id = ps.id left join pmhub_project_member pm on p.id = pm.pt_id left join sys_user su on su.user_id = p.user_id where pm.user_id = #{userId} and pm.type = 'project' and p.deleted = 0
and (p.project_code like concat('%', #{req.keyword}, '%') or p.project_name like concat('%', #{req.keyword}, '%'))
and ps.stage_code = #{req.stageCode}
and p.status = #{req.status}
and p.published = #{req.published}
and p.type = #{req.projectType}
order by p.created_time desc
